'use strict';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const arrow='<span class="arrow" aria-hidden="true">→</span>';
const icons={search:'<circle cx="9" cy="9" r="6.5"/><path d="m14 14 6 6"/>',menu:'<path d="M3 7h18M3 12h18M3 17h18"/>',leaf:'<path d="M24 38V16m0 9C9 25 9 9 9 9c15 0 15 16 15 16Zm0-6C24 4 40 4 40 4s0 15-16 15Z"/>',factory:'<path d="M6 41V18l11-7v12l12-7v8h13v17H6ZM11 41V30h24v11M6 18V8h7v6M18 32v9m9-9v9"/>',field:'<path d="M4 40h40M6 34c8-15 28-15 36 0M10 40c6-15 22-15 28 0M24 3v15M15 10l9 5 9-5M16 3l8 5 8-5"/>',box:'<path d="m7 14 17-9 17 9v23l-17 9-17-9V14Zm0 0 17 9 17-9M24 23v23M15 10l18 9v9"/>'};
const svg=(name)=>`<svg viewBox="0 0 ${name==='search'||name==='menu'?'24 24':'48 48'}" aria-hidden="true">${icons[name]||icons.leaf}</svg>`;
const brand=`<a class="brand" href="index.html" aria-label="КФХ Мазыра — главная">${svg('leaf')}<strong>МАЗЫРА</strong><span>Крестьянское хозяйство</span></a>`;
const products=window.MAZYRA_PRODUCTS;
const productImage=p=>`<img class="package-photo" src="${p.image}" alt="Упаковка: ${p.name}" loading="lazy" width="600" height="648">`;
function card(p){return `<article class="product-card reveal"><a class="product-image" href="product.html?id=${p.id}" aria-label="${p.name}">${productImage(p)}</a><span class="product-category">${p.type}</span><h3><a href="product.html?id=${p.id}">${p.name}</a></h3><a class="text-link" href="product.html?id=${p.id}">Смотреть продукт ${arrow}</a></article>`;}
function photo(src,alt,extra=''){if(extra==='brand-art')return `<div class="photo-wrap brand-art"><img src="assets/brand-logo-transparent.png" alt="${alt}" width="1254" height="1254" loading="lazy"><span class="brand-decor" aria-hidden="true"></span></div>`;return `<div class="photo-wrap ${extra}"><img src="assets/${src}.${src.startsWith('blizhnyaya-dacha') ? 'png' : 'jpg'}" alt="${alt}" width="1200" height="900" loading="lazy"></div>`;}
function form(subject='Запрос ассортимента',full=false){return `<form class="contact-form" data-subject="${subject}"><label>Ваше имя *<input name="name" autocomplete="name" required maxlength="100"></label>${full?'<div class="split-fields"><label>Компания<input name="company" autocomplete="organization" maxlength="150"></label><label>Телефон<input name="phone" type="tel" autocomplete="tel" maxlength="40"></label></div>':''}<label>Электронная почта *<input type="email" name="email" autocomplete="email" required maxlength="150"></label><label>Направление сотрудничества<select name="channel"><option value="">Выберите направление</option><option>Розничные сети и СТМ</option><option>Оптовые поставки</option><option>Пищевое производство</option><option>Рестораны и кафе</option><option>Другой вопрос</option></select></label>${full?'<label>Ваш вопрос *<textarea name="message" required maxlength="3000"></textarea></label>':''}<label class="check"><input type="checkbox" required><span>Я ознакомился с <a href="privacy.html" style="text-decoration:underline">условиями обработки данных</a> и согласен передать их по электронной почте.</span></label><button class="btn" type="submit">Подготовить запрос ${arrow}</button><p class="form-note">Откроется ваше почтовое приложение с готовым письмом на info@kfh-m.ru. Отправку вы подтверждаете сами.</p><div class="form-status" role="status" aria-live="polite"></div></form>`;}
function partner(){return `<section class="section"><div class="container"><div class="partner-box reveal"><div class="partner-copy"><h2 class="display">Давайте растить<br>сотрудничество.</h2><p>Расскажите, какие продукты нужны вашему бизнесу. Обсудим ассортимент, формат упаковки и выпуск под вашей маркой.</p></div>${form()}</div></div></section>`;}
function heading(title,desc=''){return crHeading(title,desc);}
function header(){const groups=[['О хозяйстве',[['about.html','Наша история'],['journey.html','От поля до упаковки'],['where-we-grow.html','Где выращиваем'],['our-customers.html','Наши клиенты']]],['Сила заморозки',[['the-power-of-frozen-food.html','Преимущества заморозки'],['quality.html','Качество'],['the-power-of-frozen-food-2.html','Развитие продуктов'],['foodservice-range.html','Для профессиональной кухни']]],['Наша продукция',[['frozen-vegetables.html','Наш ассортимент'],['products.html','Все продукты'],['products.html?category=vegetables','Овощи'],['products.html?category=mixes','Овощные смеси'],['products.html?category=prepared','Полуфабрикаты'],['products.html?category=fruit','Фрукты и ягоды']]]];$('#header').innerHTML=`<div class="container header-row">${brand}<nav class="desktop-nav" aria-label="Основная навигация">${groups.map(([t,links])=>`<div class="nav-group"><button aria-expanded="false">${t}</button><div class="dropdown">${links.map(([u,l])=>`<a href="${u}">${l}</a>`).join('')}</div></div>`).join('')}<a href="recipes.html">Рецепты</a><a class="nav-contact" href="our-customers.html">Для партнёров ↗</a></nav><div class="header-actions"><nav class="platform-switch" aria-label="Переключение площадки"><a href="index.html" aria-current="page">Сайт</a><a href="crm/">CRM · демо</a></nav><button class="icon-btn" data-search aria-label="Поиск по продукции">${svg('search')}</button><button class="icon-btn mobile-toggle" data-menu aria-controls="mobileMenu" aria-label="Открыть меню" aria-expanded="false">${svg('menu')}</button></div></div>`;}
function footer(){ $('#footer').innerHTML=`<div class="container"><div class="footer-grid"><div><a href="index.html" class="footer-brand">КФХ Мазыра</a><p class="footer-address">Московская область, Лобня<br>ул. Гагарина, 10, к. 2<br><a href="tel:+74957740268">+7 (495) 774-02-68</a><br><a href="mailto:info@kfh-m.ru">info@kfh-m.ru</a></p></div><div><h3>О хозяйстве</h3><nav class="footer-links"><a href="about.html">Наша история</a><a href="journey.html">От поля до упаковки</a><a href="quality.html">Качество</a><a href="where-we-grow.html">Где выращиваем</a><a href="our-customers.html">Наши клиенты</a><a href="retail-customers.html">Рознице</a><a href="industry-customers.html">Производствам</a><a href="foodservice-customers.html">Ресторанам</a></nav></div><div><h3>Продукция</h3><nav class="footer-links"><a href="products.html">Весь ассортимент</a><a href="products.html?category=vegetables">Замороженные овощи</a><a href="products.html?category=mixes">Овощные смеси</a><a href="products.html?category=prepared">Полуфабрикаты</a><a href="products.html?category=fruit">Фрукты и ягоды</a><a href="the-power-of-frozen-food.html">Сила заморозки</a><a href="foodservice-range.html">Для кухни</a></nav></div><div><h3>Будем на связи</h3><nav class="footer-links"><a href="crm/">CRM · демонстрация</a><a href="contact.html">Контакты</a><a href="recipes.html">Идеи для кухни</a><a href="faq.html">Вопросы и ответы</a><a href="contact.html?topic=stm">Производство под СТМ</a></nav></div></div><div class="footer-bottom"><p>© ${new Date().getFullYear()} КФХ Мазыра С. Ю.<br>Упаковки и фото производства — с официального сайта КФХ Мазыра. Фото рецептов — Crop’s. Часть изображений разделов носит иллюстративный характер.</p><a href="privacy.html">Обработка данных и файлы cookie</a></div></div>`;}
function home(){return `<section class="hero"><img class="hero-photo" src="assets/hero-crops-wide.jpg" alt="Овощное блюдо и тарелки с овощами, ягодами и ингредиентами в асимметричной композиции" width="2400" height="1697" fetchpriority="high"><div class="container hero-copy"><span class="eyebrow">КФХ Мазыра · овощи и полуфабрикаты</span><h1 class="display">Вкус начинается<br>с земли.</h1><a class="btn" href="products.html">Найдите свой продукт ${arrow}</a><p class="hero-note">Выращиваем. Перерабатываем. Сохраняем вкус.</p></div></section><section class="section intro container"><h2 class="reveal">Овощи с полей.<br>Возможности для вашей кухни.</h2><div class="intro-grid"><div class="reveal">${photo('blizhnyaya-dacha-frost-square','Ближняя Дача — логотип в окружении овощей и ягод','brand-art')}</div><div class="intro-copy reveal"><p>Хорошая еда начинается задолго до кухни. С земли, внимания к сырью и людей, которые знают своё дело.</p><p>Мы соединяем сельское хозяйство и переработку, чтобы овощи было удобно использовать каждый день.</p><ul class="intro-list"><li><strong>Выращиваем в российских регионах.</strong>Наши сельскохозяйственные площади находятся в Рязанской, Тульской и Московской областях.</li><li><strong>Делаем больше, чем отдельные овощи.</strong>В ассортименте — овощные смеси и полуфабрикаты для разных блюд и способов приготовления.</li><li><strong>Работаем с вашим бизнесом.</strong>Обсуждаем оптовые поставки и производство под собственной торговой маркой заказчика.</li></ul><a class="text-link" href="about.html">Наша история ${arrow}</a></div></div><div class="facts"><div class="fact reveal">${svg('leaf')}<p>Сельское хозяйство<br>и переработка</p></div><div class="fact reveal">${svg('factory')}<p>Производство<br>в Лобне</p></div><div class="fact reveal">${svg('field')}<p>Поля в трёх<br>регионах</p></div><div class="fact reveal">${svg('box')}<p>Выпуск продукции<br>под СТМ</p></div></div></section><section class="section container"><div class="journey reveal">${photo('farm','Руки фермера с урожаем на овощном поле')}<div class="journey-copy"><span class="eyebrow">От земли к вашему столу</span><h2>Растить с заботой.<br>Сохранять со вкусом.</h2><p>Поле, переработка, фасовка — у каждого этапа своя задача. Узнайте, как устроена наша работа с овощами и почему внимание к деталям важно на всём пути.</p><a class="btn outline" href="journey.html">Пройти весь путь ${arrow}</a></div></div></section><section class="section container"><h2 class="reveal">Что нужно вашему бизнесу?</h2><div class="buyers"><article class="buyer reveal">${photo('food','Блюдо из овощей для розничного ассортимента')}<h3>Розничные сети</h3><p>Продукция для вашей полки. Обсудим ассортимент и выпуск под собственной торговой маркой.</p><a class="btn outline" href="retail-customers.html">Для розницы ${arrow}</a></article><article class="buyer reveal">${photo('frozen','Замороженные овощи для оптовых поставок')}<h3>Производители продуктов</h3><p>Овощи, смеси и полуфабрикаты под задачи пищевого производства. Обсудим требования к сырью.</p><a class="btn outline" href="industry-customers.html">Для производства ${arrow}</a></article><article class="buyer reveal">${photo('food','Готовые овощи для ресторанного меню')}<h3>Рестораны и кафе</h3><p>Основа для гарниров, супов и закусок. Выбирайте продукты под задачи вашей кухни.</p><a class="btn outline" href="foodservice-customers.html">Для HoReCa ${arrow}</a></article></div></section><section class="section container"><div class="section-head reveal"><div><h2>Найдите свой продукт</h2><p>От одного ингредиента до основы готового блюда. Выбирайте овощи, сочетайте вкусы и находите новые решения для своего меню.</p></div><a class="text-link" href="products.html">Весь ассортимент ${arrow}</a></div><div class="products-grid">${['broccoli','wok','croquettes','raspberry'].map(id=>products.find(p=>p.id===id)).map(card).join('')}</div></section><section class="gallery-section container"><div class="gallery reveal">${photo('farm','Урожай в руках фермера')}${photo('food','Овощное блюдо крупным планом')}${photo('frozen','Свежий взгляд на замороженные овощи')}</div></section>${partner()}`;}
function catalog(){return `${heading('Наш ассортимент','Овощи, смеси и полуфабрикаты. Найдите подходящий продукт для своей кухни или бизнеса.')}<section class="section container" style="padding-top:20px"><div class="catalog-layout"><aside class="filter-panel"><h2>Фильтры</h2><input class="catalog-search" type="search" id="catalogSearch" placeholder="Название продукта" aria-label="Поиск продукта"><div class="filters">${[['all','Все продукты'],['vegetables','Овощи'],['mixes','Овощные смеси'],['prepared','Полуфабрикаты'],['fruit','Фрукты и ягоды']].map(([v,l])=>`<label><input type="radio" name="category" value="${v}">${l}</label>`).join('')}</div><button class="filter-reset" id="resetFilters">Сбросить фильтры</button></aside><div><div class="catalog-toolbar"><span id="productCount" aria-live="polite"></span><label>Порядок: <select id="productSort"><option value="default">Рекомендуем</option><option value="asc">Название А — Я</option><option value="desc">Название Я — А</option></select></label></div><div class="products-grid catalog-grid" id="catalogGrid"></div><p class="catalog-note">18 позиций из опубликованного ассортимента КФХ Мазыра. На фото — упаковки с официального сайта. Актуальные фасовки, наличие и условия поставки уточняйте при заказе.</p></div></div></section>${partner()}`;}
function productPage(){const p=products.find(p=>p.id===new URLSearchParams(location.search).get('id'));if(!p)return `${heading('Продукт не найден','Возможно, ссылка устарела. Все доступные позиции собраны в каталоге.')}<div class="container"><a class="btn" href="products.html">Вернуться в каталог ${arrow}</a></div>`;document.title=p.name+' — КФХ Мазыра';return `${heading(p.name)}<section class="section container" style="padding-top:20px"><div class="product-detail"><div class="reveal"><span class="eyebrow">${p.type}</span><h2>Простой ингредиент.<br>Много возможностей.</h2><p>${p.detail}</p><div class="specs"><div><span>Категория</span><strong>${p.type}</strong></div><div><span>Фасовка и наличие</span><span>По запросу</span></div><div><span>Состав и хранение</span><span>В спецификации</span></div></div><button class="btn" data-inquiry="${p.name}">Запросить информацию ${arrow}</button><p class="catalog-note">Перед заказом запросите актуальную спецификацию. На фото — упаковка из опубликованного ассортимента производителя.</p></div><div class="product-image reveal">${productImage(p)}</div></div></section><section class="section container"><div class="section-head"><h2>Вам также может подойти</h2><a class="text-link" href="products.html">Весь ассортимент ${arrow}</a></div><div class="products-grid">${[...products.filter(x=>x.id!==p.id&&x.category===p.category),...products.filter(x=>x.category!==p.category)].slice(0,4).map(card).join('')}</div></section>`;}
function about(){return `${heading('Земля. Люди. Вкус.','Крестьянско-фермерское хозяйство Мазыра С. Ю. — сельское хозяйство и переработка овощной продукции.')}<section class="section container"><div class="article-grid reveal">${photo('farm','Урожай с овощного поля')}<div><span class="eyebrow">Наша история</span><h2>Знаем, откуда<br>начинается еда.</h2><p>Работа с овощами начинается на поле. Для нас выращивание и переработка — части одного пути, на котором важны сырьё, технология и внимание к готовому продукту.</p><p>С 2015 года предприятие развивает переработку сельскохозяйственной продукции. Производство находится в Лобне Московской области.</p><p>Выпускаем замороженные овощи и полуфабрикаты, в том числе под торговыми марками «Лесотека», «Ближняя Дача» и СТМ заказчиков.</p><a class="text-link" href="journey.html">Посмотреть наш путь ${arrow}</a></div></div></section><section class="section container"><h2>Ближе к земле.<br>Ближе к вашему делу.</h2><div class="story-steps"><div class="story-step reveal"><span>01</span><h3>Выращивание</h3><p>Сельскохозяйственные площади расположены в Рязанской, Тульской и Московской областях.</p></div><div class="story-step reveal"><span>02</span><h3>Переработка</h3><p>Производство овощной продукции и полуфабрикатов в Московской области.</p></div><div class="story-step reveal"><span>03</span><h3>Сотрудничество</h3><p>Работаем с оптовыми покупателями и рассматриваем проекты под торговой маркой заказчика.</p></div></div></section>${partner()}`;}
function journey(){return `${heading('От поля до упаковки','У хорошего продукта есть своя история. Она начинается с земли и продолжается в каждом этапе работы.')}<section class="section container"><div class="article-grid reveal"><div><span class="eyebrow">Начало пути</span><h2>Растить — значит<br>внимательно относиться.</h2><p>Земля, сезон и сам урожай задают основу будущего продукта. Наши сельскохозяйственные площади находятся в трёх регионах России.</p><p>Дальше начинается работа производства: подготовка овощей, переработка и фасовка. Условия выпуска и параметры конкретного продукта фиксируются в его документации.</p><a class="btn outline" href="quality.html">О качестве ${arrow}</a></div>${photo('farm','Сбор овощей на поле')}</div><div class="story-steps"><div class="story-step reveal"><span>01</span><h3>Поле и урожай</h3><p>Сельское хозяйство в Рязанской, Тульской и Московской областях.</p></div><div class="story-step reveal"><span>02</span><h3>Подготовка и заморозка</h3><p>Переработка овощей с применением технологии шоковой заморозки.</p></div><div class="story-step reveal"><span>03</span><h3>Фасовка и поставка</h3><p>Выпуск продукции и согласование формата поставки с партнёром.</p></div></div></section>${partner()}`;}
function quality(){return `${heading('Сохранять лучшее','Внимание к сырью и технологии — основа работы с замороженной продукцией.')}<section class="section container"><div class="article-grid reveal">${photo('frozen','Овощи с тонким слоем инея')}<div><span class="eyebrow">Производство и качество</span><h2>За вкусом стоит<br>работа на каждом этапе.</h2><p>Производство КФХ Мазыра расположено в Лобне. При переработке овощей применяется технология шоковой заморозки.</p><p>Для выбора продукции под ваши задачи запросите спецификацию: точный состав, формат упаковки, условия хранения и рекомендации по приготовлению.</p><a class="btn" href="contact.html?topic=quality">Запросить документы ${arrow}</a></div></div></section><section class="section container" id="freezing"><h2>Почему замороженные овощи?</h2><div class="story-steps"><div class="story-step reveal"><span>01</span><h3>Под рукой</h3><p>Нужные ингредиенты удобно держать в морозильной камере и доставать для конкретного блюда.</p></div><div class="story-step reveal"><span>02</span><h3>Разные сценарии</h3><p>Супы, гарниры, блюда на сковороде — выбирайте продукт под способ приготовления.</p></div><div class="story-step reveal"><span>03</span><h3>Понятная порция</h3><p>Можно использовать необходимое количество, соблюдая условия хранения на упаковке.</p></div></div></section>${partner()}`;}
function partners(){return `${heading('Ваш продукт. Наше дело.','Выберите направление сотрудничества — обсудим, что нужно именно вашему бизнесу.')}<section class="section container"><div class="article-grid reveal" id="retail">${photo('food','Овощное блюдо для розничного ассортимента')}<div><span class="eyebrow">Розничные сети и СТМ</span><h2>Для вашей полки.<br>Под вашей маркой.</h2><p>КФХ Мазыра работает с продукцией под собственной торговой маркой заказчика. Начнём с задачи: категория, ассортимент и формат упаковки.</p><a class="btn" href="contact.html?topic=stm">Обсудить СТМ ${arrow}</a></div></div></section><section class="section container" id="wholesale"><div class="journey reveal">${photo('frozen','Овощи для оптового ассортимента')}<div class="journey-copy"><span class="eyebrow">Оптовые покупатели</span><h2>Новые возможности<br>для вашего ассортимента.</h2><p>Уточните доступные позиции, параметры партии и условия поставки. Мы заинтересованы в сотрудничестве с оптовыми покупателями и дистрибьюторами.</p><a class="btn outline" href="contact.html?topic=wholesale">Обсудить поставки ${arrow}</a></div></div></section><section class="section container" id="foodservice"><div class="article-grid reveal"><div><span class="eyebrow">Рестораны и кафе</span><h2>Больше идей<br>для вашей кухни.</h2><p>Подберите овощи, смеси и полуфабрикаты под задачи меню. Актуальный ассортимент, состав и варианты фасовки предоставим по запросу.</p><a class="btn" href="products.html">Выбрать продукты ${arrow}</a></div>${photo('food','Овощной гарнир для ресторанной кухни')}</div></section>${partner()}`;}
function recipes(){let rs=[['Овощи на сковороде','food','Смесь для Wok, немного масла и любимый соус.','Разогрейте сковороду. Приготовьте овощную смесь в соответствии с инструкцией на упаковке, добавьте соус и подайте с рисом или лапшой.'],['Нежный суп с брокколи','frozen','Брокколи, картофель и овощной бульон.','Отварите картофель в бульоне, добавьте брокколи и доведите до готовности. Измельчите блендером, приправьте по вкусу. Учитывайте инструкцию по приготовлению овощей.'],['Зелёная паста','food','Шпинат, паста и сливочный соус.','Отварите пасту. Приготовьте шпинат по инструкции на упаковке, соедините со сливочным соусом и пастой. Добавьте сыр по вкусу.']];return `${heading('На кухне — просто','Несколько идей, с которых удобно начать. Пропорции выбирайте по вкусу, а рекомендации по обработке — на упаковке продукта.')}<section class="section container"><div class="recipe-grid">${rs.map(([t,img,d,steps])=>`<article class="recipe-card reveal"><img src="assets/${img}.jpg" width="900" height="900" alt="Иллюстрация овощного блюда" loading="lazy"><h2>${t}</h2><p>${d}</p><details><summary>Как приготовить</summary><p>${steps}</p></details></article>`).join('')}</div></section><section class="section container"><div class="section-head"><h2>Начните с ингредиентов</h2><a class="text-link" href="products.html">Выбрать продукты ${arrow}</a></div><div class="products-grid">${['broccoli','wok','croquettes','raspberry'].map(id=>products.find(p=>p.id===id)).map(card).join('')}</div></section>`;}
function contact(){let topic=new URLSearchParams(location.search).get('topic');let subject=({stm:'Производство под СТМ',wholesale:'Оптовые поставки',industry:'Продукция для пищевого производства',foodservice:'Ассортимент для профессиональной кухни',quality:'Запрос документов'})[topic]||'Сотрудничество с КФХ Мазыра';return `${heading('Будем на связи','Расскажите о вашей задаче. Обсудим продукцию, поставки или выпуск под вашей торговой маркой.')}<section class="section container" style="padding-top:15px"><div class="contact-layout"><div class="contact-page-form reveal"><h2 style="margin-bottom:30px">${subject}</h2>${form(subject,true)}</div><aside class="contact-details reveal"><h2>КФХ Мазыра С. Ю.</h2><span class="eyebrow">Контакты</span><p><a href="tel:+74957740268">+7 (495) 774-02-68</a><br><a href="mailto:info@kfh-m.ru">info@kfh-m.ru</a></p><p>Московская область, Лобня,<br>ул. Гагарина, 10, к. 2</p><p>Чтобы подготовить предложение, укажите интересующие продукты, предполагаемый объём и город поставки.</p><a class="text-link" href="faq.html">Вопросы и ответы ${arrow}</a></aside></div></section>`;}
function faq(){let qs=[['Как получить актуальный ассортимент?','Напишите на info@kfh-m.ru или подготовьте запрос через форму контактов. Укажите интересующие категории и направление вашего бизнеса.'],['Можно ли выпускать продукцию под нашей маркой?','КФХ Мазыра работает под СТМ заказчиков. Ассортимент, упаковка, объёмы и другие параметры проекта согласовываются индивидуально.'],['Где находится производство?','В Лобне Московской области, ул. Гагарина, 10, к. 2. Контакты для обсуждения сотрудничества указаны на странице «Контакты».'],['Как узнать фасовку, состав и условия хранения?','Запросите актуальную спецификацию на конкретный продукт. Сведения на маркировке поставляемой партии имеют приоритет при хранении и приготовлении.'],['Какие минимальные объёмы и регионы доставки?','Условия и возможность поставки нужно согласовать с командой КФХ. Укажите объём, город и интересующий ассортимент в обращении.'],['Отправляет ли форма сообщение автоматически?','Нет. Кнопка подготавливает письмо в вашем почтовом приложении. Проверьте его и самостоятельно нажмите «Отправить». Если почтовое приложение не настроено, напишите напрямую на info@kfh-m.ru.']];return `${heading('Вопросы и ответы')}<section class="section container"><div class="faq">${qs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section>${partner()}`;}
function privacy(){return `${heading('Данные и файлы cookie')}<section class="section container"><div class="policy"><h2>Как работает обращение</h2><p>Форма на сайте подготавливает письмо в вашем почтовом приложении. Данные формы не сохраняются на сервере этого сайта. Отправка происходит только после вашего подтверждения в почтовом приложении.</p><h2>Какие сведения вы передаёте</h2><p>Имя, электронная почта и сведения, которые вы сами добавите в обращение. Для подготовки ответа не указывайте лишние персональные или конфиденциальные данные.</p><h2>Настройки браузера</h2><p>Сайт запоминает закрытие уведомления через localStorage. Аналитические и рекламные cookie в этой версии не используются. Внешние шрифты загружаются с Google Fonts; браузер обращается к соответствующим серверам.</p><h2>Контакт</h2><p>По вопросам, связанным с обращением, напишите на <a href="mailto:info@kfh-m.ru">info@kfh-m.ru</a>.</p></div></section>`;}
const recipeData=window.MAZYRA_RECIPES;
const imageTag=(src,alt,cls='')=>`<img class="${cls}" src="${src}" alt="${alt}" loading="lazy" width="1000" height="750">`;
const textLink=(url,label)=>`<a class="text-link" href="${url}">${label} ${arrow}</a>`;
function editorial(title,subtitle){return heading(title,subtitle);}
function splitStory(title,paragraphs,img,alt,cta='',reverse=false){return `<section class="section container"><div class="editorial-split ${reverse?'reverse':''}"><div class="editorial-text reveal"><h2>${title}</h2>${paragraphs.map(x=>`<p>${x}</p>`).join('')}${cta.replace('class="text-link"','class="cr-button"')}</div><div class="editorial-image reveal">${imageTag(img,alt)}</div></div></section>`;}
function numbers(){return `<section class="container metric-strip"><div><strong>3</strong><span>региона выращивания</span></div><div><strong>2015</strong><span>развитие переработки</span></div><div><strong>до 1,5 млн</strong><span>пачек в месяц — мощность производства</span></div><div><strong>Лобня</strong><span>Московская область</span></div></section>`;}
function productSelection(title='Найдите свой продукт',cat='',limit=4){const list=products.filter(p=>!cat||p.category===cat).slice(0,limit);return `<section class="cr-section cr-carousel-section"><div class="container"><div class="cr-slider-heading"><h2>${title}</h2>${crMinimal('products.html'+(cat?'?category='+cat:''),'Все продукты')}</div><div class="cr-carousel" data-cr-carousel>${list.map(p=>`<article class="cr-product-card"><a class="cr-product-visual" href="product.html?id=${p.id}">${productImage(p)}</a><h3><a href="product.html?id=${p.id}">${p.name}</a></h3><p>${p.desc}</p>${crMinimal('product.html?id='+p.id,'Смотреть продукт')}</article>`).join('')}</div><div class="cr-carousel-controls"><button type="button" data-cr-prev aria-label="Предыдущие продукты">←</button><button type="button" data-cr-next aria-label="Следующие продукты">→</button></div></div></section>`;}
function recipeCard(r){return `<article class="inspiration-card"><a class="recipe-photo" href="recipes/${r.id}/">${imageTag(r.image,r.name)}</a><div class="recipe-copy"><div class="recipe-tags">${r.tags.slice(0,2).map(t=>`<span>${t}</span>`).join('')}</div><h3><a href="recipes/${r.id}/">${r.name}</a></h3><p>На ${r.people} порции · ${r.ingredients.length} ингредиентов</p>${textLink('recipes/'+r.id+'/','Как приготовить')}</div></article>`;}
function recipeSelection(ids=[0,17,20,30]){return `<section class="cr-section cr-carousel-section"><div class="container"><div class="cr-slider-heading"><h2>Идеи для вашей кухни</h2>${crMinimal('recipes.html','Все рецепты')}</div><div class="cr-carousel" data-cr-carousel>${ids.map(i=>{const r=recipeData[i];return `<article class="cr-recipe-card"><a class="cr-recipe-visual" href="recipes/${r.id}/">${imageTag(r.image,r.name)}</a><div class="cr-recipe-body"><h3><a href="recipes/${r.id}/">${r.name}</a></h3><p>На ${r.people} порции · ${r.ingredients.length} ингредиентов</p>${crMinimal('recipes/'+r.id+'/','Как приготовить')}</div></article>`}).join('')}</div><div class="cr-carousel-controls"><button type="button" data-cr-prev aria-label="Предыдущие рецепты">←</button><button type="button" data-cr-next aria-label="Следующие рецепты">→</button></div></div></section>`;}
function fieldsPage(){return `${editorial('Где мы выращиваем','Земля, с которой начинается наш продукт')}${splitStory('Три региона.<br>Одна забота о сырье.',['Сельскохозяйственные площади КФХ Мазыра находятся в Рязанской и Тульской областях, а также на юге Московской области.','Почва и природные условия этих регионов создают основу для выращивания сельскохозяйственного сырья. С 2015 года хозяйство развивает переработку овощей и производство замороженной продукции.'],'assets/official/fields.jpg','Сельскохозяйственный пейзаж с официального сайта КФХ Мазыра',textLink('journey.html','От поля до упаковки'))}${numbers()}<section class="section container"><div class="section-head"><div><span class="eyebrow">Наши регионы</span><h2>Близость к земле</h2></div></div><div class="region-layout"><div class="region-map">${imageTag('assets/official/regions.png','Регионы сельского хозяйства КФХ Мазыра')}</div><div class="region-content"><div class="region-tabs" role="tablist" aria-label="Регионы выращивания">${['Рязанская область','Тульская область','Московская область'].map((x,i)=>`<button role="tab" id="region-tab-${i}" aria-controls="region-panel-${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-region="${i}">${x}</button>`).join('')}</div>${['Рязанская область','Тульская область','Юг Московской области'].map((x,i)=>`<div class="region-panel" role="tabpanel" id="region-panel-${i}" aria-labelledby="region-tab-${i}" ${i?'hidden':''}><h3>${x}</h3><p>${['Один из регионов, где расположены сельскохозяйственные площади хозяйства. Чернозёмные районы дают основу для выращивания сырья.','Сельскохозяйственные площади в чернозёмных районах Тульской области входят в географию КФХ Мазыра.','Юг Московской области дополняет географию выращивания. Производство и переработка расположены в Лобне.'][i]}</p><dl class="region-facts"><div><dt>Направление</dt><dd>Сельскохозяйственное сырьё</dd></div><div><dt>Переработка</dt><dd>Лобня, Московская область</dd></div></dl>${textLink('contact.html','Связаться с хозяйством')}</div>`).join('')}</div></div></section>${splitStory('Продолжаем путь<br>на производстве.',['Подготовка сырья, переработка, заморозка и фасовка соединяют урожай с готовой упаковкой. Познакомьтесь с нашей работой и ассортиментом.'],'assets/official/i1.jpg','Подготовка брокколи на производственной линии',textLink('quality.html','Качество и производство'),true)}${partner()}`;}
const customerSegments=[{id:'retail',name:'Розничным сетям',subtitle:'Продукция для вашей полки',img:'assets/food.jpg',url:'retail-customers.html'},{id:'industry',name:'Производителям',subtitle:'Ингредиенты для ваших процессов',img:'assets/official/i3.jpg',url:'industry-customers.html'},{id:'foodservice',name:'Ресторанам и кафе',subtitle:'Решения для вашей кухни',img:'assets/recipes/grilled-veg-lasagna.jpg',url:'foodservice-customers.html'}];
const crButton=(url,label)=>`<a class="cr-button" href="${url}"><span>${label}</span><svg viewBox="0 0 16 8" aria-hidden="true"><path d="M12 8V5H0V3h12V0l4 4-4 4z"/></svg></a>`;
const crMinimal=(url,label)=>`<a class="cr-minimal" href="${url}">${label}<svg viewBox="0 0 16 8" aria-hidden="true"><path d="M12 8V5H0V3h12V0l4 4-4 4z"/></svg></a>`;
function crHeading(title,sub=''){return `<section class="cr-heading"><div class="container"><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div></section>`;}
function crSplit(copy,image,alt,{tint=false,reverse=false}={}){return `<section class="cr-section cr-split-section ${tint?'cr-tint':''}"><div class="container cr-split ${reverse?'cr-reverse':''}"><div class="cr-copy">${copy}</div><div class="cr-visual">${imageTag(image,alt)}</div></div></section>`;}
function crProductSlider(category,ids){const list=ids.map(id=>products.find(p=>p.id===id)).filter(Boolean);return `<section class="cr-section cr-carousel-section"><div class="container"><div class="cr-slider-heading"><h2>Найдите свой продукт</h2>${crMinimal('products.html'+(category?'?category='+category:''),'Все продукты')}</div><div class="cr-carousel" data-cr-carousel>${list.map(p=>`<article class="cr-product-card"><a class="cr-product-visual" href="product.html?id=${p.id}">${productImage(p)}</a><h3><a href="product.html?id=${p.id}">${p.name}</a></h3><p>${p.desc}</p>${crMinimal('product.html?id='+p.id,'Смотреть продукт')}</article>`).join('')}</div><div class="cr-carousel-controls"><button type="button" data-cr-prev aria-label="Предыдущие продукты">←</button><button type="button" data-cr-next aria-label="Следующие продукты">→</button></div></div></section>`;}
function crRecipeSlider(){return `<section class="cr-section cr-carousel-section"><div class="container"><div class="cr-slider-heading"><h2>Идеи для вашей кухни</h2>${crMinimal('recipes.html','Все рецепты')}</div><div class="cr-carousel" data-cr-carousel>${[20,25,21,16].map(i=>{const r=recipeData[i];return `<article class="cr-recipe-card"><a class="cr-recipe-visual" href="recipes/${r.id}/">${imageTag(r.image,r.name)}</a><div class="cr-recipe-body"><h3><a href="recipes/${r.id}/">${r.name}</a></h3><p>Овощное блюдо на ${r.people} порции. Ингредиенты и пошаговое приготовление.</p>${crMinimal('recipes/'+r.id+'/','Читать рецепт')}</div></article>`}).join('')}</div><div class="cr-carousel-controls"><button type="button" data-cr-prev aria-label="Предыдущие рецепты">←</button><button type="button" data-cr-next aria-label="Следующие рецепты">→</button></div></div></section>`;}
function customersPage(){return `<div class="cr-client-page">${crHeading('Наши клиенты','Чем мы можем вам помочь?')}${crSplit(`<h2>Найдите своё решение</h2><p>КФХ Мазыра объединяет сельское хозяйство, переработку овощей и внимание к тому, как продукт используется на кухне. Мы выпускаем <strong>овощи, смеси и полуфабрикаты</strong> для разных способов приготовления.</p><p>В ассортименте есть отдельные ингредиенты, готовые овощные сочетания и горячие закуски. Продукция выходит под марками <strong>«Ближняя Дача», «Лесотека»</strong>, а также под собственной торговой маркой заказчика.</p><p>Сельскохозяйственные площади расположены в Рязанской, Тульской и Московской областях.</p><ul><li>Переработка и выпуск продукции в Лобне</li><li>Работа с ассортиментом и упаковкой под СТМ</li><li>Согласование решения под задачи вашего бизнеса</li></ul><p>Ищете продукты для своей полки, производства или кухни?</p>`,'assets/clients/our-customers-1.jpg','Овощные блюда — варианты подачи',{tint:true})}<section class="cr-section"><div class="container cr-link-grid">${[{name:'Решения для розницы',button:'Розничным сетям',url:'retail-customers.html',image:'our-customers-2.jpg'},{name:'Решения для производства',button:'Производителям',url:'industry-customers.html',image:'our-customers-3.jpg'},{name:'Решения для кухни',button:'Ресторанам и кафе',url:'foodservice-customers.html',image:'our-customers-4.jpg'}].map(x=>`<article class="cr-link-card"><a class="cr-link-photo" href="${x.url}">${imageTag('assets/clients/'+x.image,x.name)}</a><h2>${x.name}</h2>${crButton(x.url,x.button)}</article>`).join('')}</div></section></div>`;}
function segmentPage(kind){const d={retail:{title:'Розничным сетям',heading:'Ваш ассортимент.<br>Ваша торговая марка.',intro:[`Развивайте категорию замороженных продуктов с производителем, который работает с <strong>собственными марками и СТМ</strong>.`,`КФХ Мазыра соединяет сельскохозяйственное сырьё с переработкой. Производство находится в Лобне Московской области.`,`Под маркой «Ближняя Дача» представлены овощи, смеси, фрукты и ягоды. Крокеты и овощные фриттеры дополняют возможности для вашей полки.`,`На официальном сайте хозяйства среди партнёров по СТМ указаны <strong>ВкусВилл, Ozon и Яндекс Лавка</strong>. Параметры нового проекта согласуем с вашей командой.`,`Обсудим ваш новый продукт?`],lead:'Обсудим с вами выпуск замороженной продукции под задачи вашей сети:',benefits:['Категории и позиции для вашей полки','Требования к качеству и документации','Формат упаковки и маркировку','Проект под собственной торговой маркой','Объём партии и условия поставки','Состав и параметры конкретной позиции'],topic:'stm',tint:true,cat:'mixes',ids:['wok','asian','broccoli-soup']},industry:{title:'Производителям продуктов',heading:'Решения под задачу.<br>Ингредиенты для вашего процесса.',intro:[`Каждая рецептура предъявляет свои требования к сырью. <strong>Начнём с вашей технологии</strong>, нужного состава и формата продукта.`,`С 2015 года КФХ Мазыра развивает переработку сельскохозяйственной продукции. Предприятие в Лобне выпускает замороженные овощи и полуфабрикаты.`,`Один ингредиент или готовое сочетание — подберём позиции из опубликованного ассортимента и обсудим возможность поставки для вашего производства.`,`Состав, фасовка, документы и параметры партии согласуются для конкретной позиции. Так решение будет соответствовать <strong>вашей производственной задаче</strong>.`],lead:'Чтобы подготовить предложение для вашего производства, уточним:',benefits:['Назначение сырья и требования рецептуры','Подходящие овощи или овощные смеси','Состав и характеристики выбранной позиции','Необходимые документы на продукцию','Формат упаковки и объём партии','Условия хранения и поставки'],topic:'industry',tint:false,cat:'vegetables',ids:['asparagus','spinach','broccoli','edamame']},foodservice:{title:'Ресторанам и кафе',heading:'Для тех, кто готовит.',intro:[`От ресторанного меню до быстрой горячей закуски — профессиональной кухне нужны <strong>удобные ингредиенты и понятный результат</strong>.`,`КФХ Мазыра выпускает замороженные овощи, смеси и полуфабрикаты. Сельское хозяйство и переработка соединяются в ассортименте для разных блюд.`,`Брокколи и шпинат подходят для гарниров, супов и начинок. Смеси для Wok и супов помогают подобрать основу блюда. Крокеты с разными начинками и овощные фриттеры дополняют <strong>меню горячих закусок</strong>.`,`Какие задачи стоят перед вашей кухней?`],lead:'Выбирайте продукты под формат кухни и способ приготовления:',benefits:['Отдельные овощи для разных рецептур','Смеси для супов, гарниров и Wok','Полуфабрикаты для горячей подачи','Возможность отмерять необходимую порцию','Согласование фасовки и актуального ассортимента'],topic:'foodservice',tint:false}}[kind];const first=crSplit(`<h2>${d.heading}</h2>${d.intro.map(t=>`<p>${t}</p>`).join('')}`,'assets/clients/'+kind+'-customers-1.jpg',d.title);const second=crSplit(`<p>${d.lead}</p><ul>${d.benefits.map(t=>`<li>${t}</li>`).join('')}</ul>${crButton('contact.html?topic='+d.topic,'Связаться с нами')}`,'assets/clients/'+kind+'-customers-2.jpg','Овощи и блюда для '+d.title.toLowerCase(),{tint:d.tint,reverse:true});let after=kind==='foodservice'?`<section class="cr-section"><div class="container"><div class="cr-cta"><div class="cr-cta-visual">${imageTag('assets/packages/13-09.png','Овощное блюдо для профессиональной кухни')}</div><div class="cr-cta-copy"><p>От отдельного ингредиента до основы готового блюда. Посмотрите ассортимент КФХ Мазыра для разных задач профессиональной кухни.</p>${crButton('foodservice-range.html','Подробнее')}</div></div></div></section>${crRecipeSlider()}`:crProductSlider(d.cat,d.ids);return `<div class="cr-client-page" data-client="${kind}">${crHeading(d.title)}${first}${second}${after}</div>`;}
function vegetablesPage(){return `<section class="category-hero">${imageTag('assets/hero.jpg','Овощные блюда и ингредиенты')}<div class="container"><h1 class="display">Замороженные<br>продукты</h1></div></section><section class="section container"><div class="long-intro"><h2>Ассортимент для повседневной кухни и бизнеса</h2><p>Один ингредиент или готовое сочетание — выбирайте под своё блюдо. КФХ Мазыра выпускает замороженные овощи, смеси и полуфабрикаты. Под маркой «Ближняя Дача» на официальном сайте также представлены фрукты, ягоды и смеси для смузи.</p><a class="btn" href="contact.html">Связаться с нами ${arrow}</a></div></section><section class="section container"><h2>Что в вашей морозильной камере?</h2><div class="category-grid">${[['vegetables','Отдельные овощи','Спаржа, шпинат, брокколи и эдамамэ. Простые ингредиенты, которые легко сочетать.','broccoli'],['mixes','Овощные смеси','Для борща, супов, азиатских блюд и приготовления в Wok.','wok'],['prepared','Полуфабрикаты','Крокеты с разными начинками и овощные фриттеры.','croquettes'],['fruit','Фрукты и ягоды','Малина, фруктовый салат, ягодная смесь и сочетания для смузи.','berry-mix']].map(([c,t,d,id])=>`<article class="category-tile">${productImage(products.find(p=>p.id===id))}<h3>${t}</h3><p>${d}</p>${textLink('products.html?category='+c,'Выбрать продукты')}</article>`).join('')}</div></section>${productSelection()}${recipeSelection()}${partner()}`;}
function frozenPage(){return `<div class="cr-client-page audit-reference-page">${crHeading('Сила заморозки','Сохранить урожай. Упростить приготовление.')}${crSplit(`<h2>Овощи в запасе.<br>Идеи каждый день.</h2><p>В КФХ Мазыра применяют технологию <strong>шоковой заморозки</strong>. Замороженный формат помогает пользоваться овощами и ягодами за пределами сезона сбора.</p><p>Выбирайте нужный ингредиент, отмеряйте порцию и готовьте по рекомендациям на упаковке. Остальной продукт храните при указанных производителем условиях.</p>`,'assets/clients/frozen-benefit-1.jpg','Замороженные овощи и блюда из них')}${crSplit(`<p>Почему замороженные продукты удобны в повседневной работе?</p><h2>Качество</h2><p>Внимание к сырью и соблюдение технологии обработки важны на всём пути продукта.</p>${crButton('quality.html','Качество')}<h2 class="audit-subheading">Удобство</h2><p>Отдельные овощи и готовые сочетания помогают собрать гарнир, суп или блюдо на сковороде. Выберите формат под свою кухню.</p>`,'assets/clients/frozen-benefit-2.jpg','Приготовление овощей',{tint:true,reverse:true})}${crSplit(`<h2>Запас на кухне</h2><p>Замороженный формат позволяет планировать меню. Срок годности и условия хранения смотрите на маркировке выбранной позиции.</p><h2 class="audit-subheading">Порции по задаче</h2><p>Используйте нужное количество и соблюдайте правила хранения оставшейся продукции. Это помогает планировать расход ингредиентов.</p>${crButton('products.html','Наш ассортимент')}`,'assets/clients/frozen-benefit-3.jpg','Блюда с овощами',{tint:true})}${recipeSelection([15,21,20,24])}</div>`;}
function qualityPage(){return `<div class="cr-client-page audit-reference-page">${crHeading('Качество','Внимание к сырью и безопасности продукции')}<section class="cr-section audit-wide-quality"><div class="audit-wide-copy"><h2>Качество начинается<br>с процесса.</h2><p>Производство КФХ Мазыра находится в Лобне Московской области. По информации хозяйства, оно построено по стандартам ХАССП.</p><p>Технология шоковой заморозки применяется для выпуска овощной продукции. Для оценки конкретной позиции запросите спецификацию, сведения о составе и документы на поставку.</p>${crButton('contact.html?topic=quality','Запросить документы')}</div><div class="audit-wide-photo">${imageTag('assets/official/i1.jpg','Подготовка брокколи на производстве КФХ Мазыра')}</div></section>${numbers()}<section class="cr-section"><div class="container quality-grid">${[['Сырьё','Сельскохозяйственные площади в трёх регионах России — основа работы хозяйства.','i2.jpg'],['Переработка','Подготовка овощей и производство замороженной продукции выполняются на предприятии в Лобне.','i3.jpg'],['Информация о продукте','Состав, аллергены, срок годности и рекомендации по приготовлению уточняйте для конкретной позиции.','i5.jpg']].map(([t,d,img])=>`<article>${imageTag('assets/official/'+img,t)}<h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="cr-section"><div class="container"><div class="cr-cta"><div class="cr-cta-visual">${imageTag('assets/official/fields.jpg','Сельскохозяйственный пейзаж')}</div><div class="cr-cta-copy"><p>Проследите путь от сельскохозяйственного сырья до готовой упаковки. Поле, подготовка и заморозка — части одной истории.</p>${crButton('journey.html','От поля до упаковки')}</div></div></div></section>${auditGallery(['assets/official/i1.jpg','assets/official/i2.jpg','assets/official/i3.jpg','assets/official/i4.jpg'],'Производство КФХ Мазыра')}</div>`;}
function innovationPage(){return `<div class="cr-client-page audit-reference-page">${crHeading('Развитие продуктов','Новые решения для разных кухонь')}${crSplit(`<h2>От отдельных овощей<br>к готовым сочетаниям.</h2><p>С 2015 года КФХ Мазыра сосредоточено на переработке сельскохозяйственной продукции. Сегодня ассортимент включает овощи, смеси и полуфабрикаты.</p><p>Задача продукта может быть разной: стать основой супа, дополнить горячее блюдо или превратиться в самостоятельную закуску. Проекты под СТМ обсуждаются с учётом требований заказчика.</p>`,'assets/official/i3.jpg','Производство замороженной продукции')}${crSplit(`<h2>Начало — в сельском хозяйстве.</h2><p>Сырьё начинается с земли. Хозяйство работает в Рязанской, Тульской и Московской областях.</p><p>Подбор ингредиентов, переработка и фасовка соединяются в готовом продукте для вашего бизнеса.</p>${crButton('where-we-grow.html','Где выращиваем')}`,'assets/official/fields.jpg','Сельскохозяйственный пейзаж',{tint:true,reverse:true})}${auditGallery(['assets/official/i1.jpg','assets/official/i2.jpg','assets/official/i5.jpg'],'Переработка и фасовка овощей')}${crSplit(`<h2>Сочетания для вашей кухни.</h2><p>Смеси для супов и Wok помогают подобрать основу под способ приготовления. В ассортименте есть и отдельные овощи для собственных рецептур.</p>${crButton('products.html?category=mixes','Овощные смеси')}`,'assets/recipes/grilled-veg-with-a-crunch.jpg','Овощное блюдо')}${crSplit(`<h2>Больше форматов для подачи.</h2><p>Крокеты со шпинатом и сыром, с хамоном, картофельные крокеты с моцареллой и овощные фриттеры дополняют овощную часть ассортимента.</p>${crButton('products.html?category=prepared','Полуфабрикаты')}`,'assets/packages/07-003.png','Ближняя Дача — картофельные крокеты с моцареллой',{reverse:true})}${crSplit(`<h2>Продукт под вашей маркой.</h2><p>Есть задача для собственной марки? Обсудим категорию, формат упаковки и требования к готовой позиции.</p>${crButton('contact.html?topic=stm','Обсудить СТМ')}`,'assets/official/i5.jpg','Фасовка продукции на производстве')}${productSelection('Выберите свой продукт')}</div>`;}
function foodservicePage(){return `${editorial('Для профессиональной кухни','Ингредиенты, смеси и горячие закуски')}${splitStory('У вашего меню<br>много возможностей.',['Соберите ассортимент под формат кухни: отдельные овощи для гарниров и начинок, смеси для супов и Wok, крокеты и фриттеры для горячей подачи.','Выбирайте продукты под способ приготовления и размер порции. Состав, фасовку и актуальное наличие уточните по интересующим позициям.'],'assets/recipes/arancini-balls-with-mozarella.jpg','Горячая закуска для ресторанного меню',textLink('products.html','Найти продукт'))}<section class="section container"><div class="feature-tabs" role="tablist" aria-label="Преимущества формата">${['Сочетайте','Планируйте','Порционируйте'].map((t,i)=>`<button role="tab" id="feature-tab-${i}" aria-controls="feature-panel-${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-feature="${i}">${t}</button>`).join('')}</div>${[['Сочетайте','Один овощ может стать гарниром, начинкой или частью супа. Смеси помогут подобрать основу для конкретного блюда.','assets/recipes/grilled-veg-lasagna.jpg'],['Планируйте','Держите ингредиенты для меню в запасе и готовьте их по мере необходимости, соблюдая условия хранения.','assets/recipes/easy-root-veg-quiche.jpg'],['Порционируйте','Отмеряйте необходимое количество перед приготовлением. Не забывайте о рекомендациях на упаковке.','assets/recipes/asian-poke-bowl.jpg']].map(([t,d,img],i)=>`<div class="feature-panel" id="feature-panel-${i}" role="tabpanel" aria-labelledby="feature-tab-${i}" ${i?'hidden':''}><div>${imageTag(img,t)}</div><div><h2>${t}</h2><p>${d}</p>${textLink('products.html','Выбрать ассортимент')}</div></div>`).join('')}</section>${recipeSelection([17,22,18,24])}${partner()}`;}
function allRecipes(){return `${editorial('Рецепты','38 идей с овощами: от завтрака до ужина')}<section class="section container listing-section"><div class="catalog-layout"><aside class="filter-panel"><h2>Фильтры</h2><label class="search-label">Найти рецепт<input type="search" id="recipeSearch" placeholder="Название или ингредиент"></label><fieldset class="recipe-filters"><legend>Тип блюда</legend>${['Завтрак','Обед','Ужин','Гарнир','Закуска','Вегетарианское'].map(t=>`<label><input type="checkbox" name="recipe-type" value="${t}">${t}</label>`).join('')}</fieldset><details class="ingredient-filter"><summary>Ингредиенты</summary><div>${[...new Set(recipeData.flatMap(r=>r.ingredientTags))].sort((a,b)=>a.localeCompare(b,'ru')).map(t=>`<label><input type="checkbox" name="recipe-ingredient" value="${t}">${t}</label>`).join('')}</div></details><button class="filter-reset" id="resetRecipes">Сбросить фильтры</button></aside><div><div class="catalog-toolbar"><span id="recipeCount" aria-live="polite"></span><label>Порядок: <select id="recipeSort"><option value="default">Рекомендуем</option><option value="asc">Название А — Я</option><option value="desc">Название Я — А</option></select></label></div><div class="recipes-list" id="recipesGrid"></div><nav class="pagination" id="recipePagination" aria-label="Страницы рецептов"></nav></div></div></section>`;}
