// Dawtona-style window tracking, activated by the first contact with the artwork.
document.querySelectorAll('.brand-art').forEach(area=>{
 let active=false,visible=false,frame=0,x=0,y=0,targetX=0,targetY=0,last=0;
 const draw=time=>{
  const dt=last?Math.min(time-last,50):16; last=time;
  const blend=1-Math.exp(-dt/90);
  x+=(targetX-x)*blend;y+=(targetY-y)*blend;
  if(Math.abs(targetX-x)<.005)x=targetX;
  if(Math.abs(targetY-y)<.005)y=targetY;
  area.style.setProperty('--decor-x',`${x.toFixed(3)}px`);
  area.style.setProperty('--decor-y',`${y.toFixed(3)}px`);
  if(x!==targetX||y!==targetY)frame=requestAnimationFrame(draw);else{frame=0;last=0;}
 };
 const follow=event=>{
  const rect=area.getBoundingClientRect();
  if(!active&&event.clientX>=rect.left&&event.clientX<=rect.right&&event.clientY>=rect.top&&event.clientY<=rect.bottom)active=true;
  if(!active||rect.bottom<=0||rect.top>=innerHeight)return;
  targetX=-Math.max(-1,Math.min(1,(event.clientX-innerWidth/2)/(innerWidth/2)))*5;
  targetY=-Math.max(-1,Math.min(1,(event.clientY-innerHeight/2)/(innerHeight/2)))*5;
  if(!frame)frame=requestAnimationFrame(draw);
 };
 area.addEventListener('pointerenter',event=>{if(event.pointerType==='mouse'){active=true;follow(event);}});
 window.addEventListener('mousemove',follow,{passive:true});
 new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;},{threshold:.1}).observe(area);
});

