function bindTabs(buttonSelector,panelPrefix){const buttons=$$(buttonSelector);function activate(i,focus=false){buttons.forEach((b,n)=>{b.setAttribute('aria-selected',String(n===i));b.tabIndex=n===i?0:-1;document.getElementById(panelPrefix+n).hidden=n!==i;});if(focus)buttons[i].focus();}buttons.forEach((b,i)=>{b.addEventListener('click',()=>activate(i));b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;activate(next,true);}});});}
