// Scroll-snap carousels keep the same visual proportions as the reference.
document.querySelectorAll('.cr-carousel-section').forEach(section=>{
 const track=section.querySelector('[data-cr-carousel]');if(!track)return;
 const move=direction=>track.scrollBy({left:direction*(track.firstElementChild.getBoundingClientRect().width+parseFloat(getComputedStyle(track).columnGap)),behavior:'smooth'});
 section.querySelector('[data-cr-prev]').onclick=()=>move(-1);
 section.querySelector('[data-cr-next]').onclick=()=>move(1);
});
